from __future__ import annotations
import win32clipboard
def copy_to_clipboard(text: str) -> None: if not text: return win32clipboard.OpenClipboard() try: win32clipboard.EmptyClipboard() win32clipboard.SetClipboardData(win32clipboard.CF_UNICODETEXT, text) finally: win32clipboard.CloseClipboard()

from __future__ import annotations
from app.platform import get_platform_services
def copy_to_clipboard(text: str) -> None: get_platform_services().copy_to_clipboard(text)

from __future__ import annotations
from app.platform import get_platform_services
def inject_text(text: str) -> None: get_platform_services().inject_text(text)
